/**
 * Recurring-issue rules. Every read except the job's global sweep is org-scoped.
 */
import { and, asc, count, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp } from "./_mappers";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type { OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";

function toRecurringIssue(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    title: row.title,
    priority: row.priority as IssuePriority,
    assigneeId: row.assigneeId === null ? null : brandId<UserId>(row.assigneeId),
    cadence: row.cadence as RecurrenceCadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export async function insertRecurringIssue(
  values: Pick<
    RecurringIssue,
    | "orgId"
    | "projectId"
    | "title"
    | "priority"
    | "assigneeId"
    | "cadence"
    | "weekday"
    | "timezone"
    | "startsOn"
    | "createdBy"
  >,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      ...values,
      lastOccurrenceOn: null,
      paused: false,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function findRecurringIssue(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(recurringIssues.rowid))
    .all()
    .map(toRecurringIssue);
}

export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** The job's work list: every non-paused rule of every organization. */
export async function listActiveRecurringIssues(): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt))
    .all()
    .map(toRecurringIssue);
}

export async function setPaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return toRecurringIssue(row);
}

export async function setLastOccurrence(
  orgId: OrgId,
  id: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return toRecurringIssue(row);
}
